def _reconstruct_third_party_scorer(cls, serialized: SerializedScorer) -> "Scorer":
        """Reconstruct a third-party scorer (RAGAS, DeepEval, TruLens, Phoenix) from its
        serialized payload.

        Deserialization imports and instantiates the referenced wrapper class, so this method
        enforces a security allow-list and validates the payload before doing so.
        """
        data = serialized.third_party_scorer_data
        module_path = data.get("module") or ""
        class_name = data.get("class") or ""
        metric_name = data.get("metric_name") or ""
        model = data.get("model")
        kwargs = dict(data.get("kwargs") or {})

        if not class_name or not metric_name:
            raise MlflowException.invalid_parameter_value(
                f"Third-party scorer data is missing required fields. Both 'class' and "
                f"'metric_name' must be non-empty. Got class={class_name!r}, "
                f"metric_name={metric_name!r}."
            )

        if not any(
            module_path == allowed or module_path.startswith(allowed + ".")
            for allowed in THIRD_PARTY_SCORER_ALLOWED_MODULES
        ):
            raise MlflowException.invalid_parameter_value(
                f"Third-party scorer module '{module_path}' is not in the allow-list. "
                f"Only scorers from the following modules can be deserialized: "
                f"{sorted(THIRD_PARTY_SCORER_ALLOWED_MODULES)}."
            )

        try:
            module = importlib.import_module(module_path)
        except ImportError as e:
            raise MlflowException.invalid_parameter_value(
                f"Third-party scorer module '{module_path}' could not import: {e}"
            )

        scorer_class = getattr(module, class_name, None)
        if scorer_class is None:
            raise MlflowException.invalid_parameter_value(
                f"Third-party scorer class '{class_name}' was not found in module "
                f"'{module_path}'."
            )

        class_metric_name = getattr(scorer_class, "metric_name", None)
        if (
            isinstance(class_metric_name, str)
            and class_metric_name
            and class_metric_name != metric_name
        ):
            raise MlflowException.invalid_parameter_value(
                f"Serialized metric_name '{metric_name}' does not match class "
                f"'{class_name}' metric_name '{class_metric_name}'."
            )

        # Deterministic scorers serialize `model` as None and their constructors may not accept
        # a `model` argument, so only forward it for LLM-backed scorers.
        constructor_kwargs = dict(kwargs)
        if model is not None:
            constructor_kwargs["model"] = model
        try:
            instance = scorer_class(**constructor_kwargs)
        except Exception as e:
            raise MlflowException.invalid_parameter_value(
                f"Third-party scorer '{class_name}' failed to instantiate: {e}"
            )

        # Restore the registered display name and any core scorer fields.
        instance.name = serialized.name
        if serialized.description is not None:
            instance.description = serialized.description
        if serialized.aggregations is not None:
            instance.aggregations = serialized.aggregations
        return instance

